Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset"
  },
  "title": {
    "text": "Inside the dbt build: 4 threads, one slow Python model",
    "subtitle": "Each bar is a model, snapshot, seed or test, from start to finish (seconds since the build started)",
    "anchor": "start",
    "color": "#172541",
    "fontSize": 15,
    "fontWeight": 600,
    "subtitleColor": "#8A7F6E",
    "subtitleFontSize": 11,
    "offset": 10
  },
  "width": 720,
  "height": 200,
  "transform": [
    {
      "filter": "datum[''Thread''] != ''main'' && datum[''Started At''] != null && datum[''Completed At''] != null"
    },
    {
      "calculate": "time(toDate(datum[''Started At'']))",
      "as": "s_ms"
    },
    {
      "calculate": "time(toDate(datum[''Completed At'']))",
      "as": "e_ms"
    },
    {
      "joinaggregate": [
        {
          "op": "min",
          "field": "s_ms",
          "as": "t0"
        }
      ]
    },
    {
      "calculate": "(datum.s_ms - datum.t0) / 1000",
      "as": "start_s"
    },
    {
      "calculate": "max((datum.e_ms - datum.t0) / 1000, datum.start_s + 0.4)",
      "as": "end_s"
    },
    {
      "calculate": "datum[''status''] == ''warn'' ? ''warning'' : (datum[''status''] == ''fail'' || datum[''status''] == ''error'') ? ''failed'' : datum[''Resource Type''] == ''unit_test'' ? ''test'' : datum[''Resource Type'']",
      "as": "kind"
    },
    {
      "calculate": "''Thread '' + replace(datum[''Thread''], ''Thread-'', '''')",
      "as": "lane"
    }
  ],
  "encoding": {
    "y": {
      "field": "lane",
      "type": "nominal",
      "title": null,
      "sort": "ascending",
      "axis": {
        "domain": false,
        "ticks": false,
        "labelColor": "#8A7F6E",
        "labelFontSize": 11,
        "labelPadding": 8
      }
    },
    "x": {
      "field": "start_s",
      "type": "quantitative",
      "title": "Seconds since build start",
      "scale": {
        "domainMin": 0,
        "nice": true
      },
      "axis": {
        "domain": false,
        "ticks": false,
        "gridColor": "#F1EADB",
        "labelColor": "#8A7F6E",
        "titleColor": "#8A7F6E",
        "titleFontWeight": "normal",
        "titleFontSize": 11,
        "labelFontSize": 10,
        "tickCount": 8
      }
    }
  },
  "layer": [
    {
      "mark": {
        "type": "bar",
        "cornerRadius": 3,
        "height": {
          "band": 0.62
        },
        "stroke": "#FFFFFF",
        "strokeWidth": 1
      },
      "encoding": {
        "x2": {
          "field": "end_s"
        },
        "color": {
          "field": "kind",
          "type": "nominal",
          "title": null,
          "scale": {
            "domain": [
              "model",
              "snapshot",
              "seed",
              "test",
              "warning",
              "failed"
            ],
            "range": [
              "#14617E",
              "#F2B632",
              "#B8860B",
              "#A9CCD8",
              "#E8833A",
              "#AD2F4B"
            ]
          },
          "legend": {
            "orient": "bottom",
            "direction": "horizontal",
            "symbolType": "square",
            "labelColor": "#8A7F6E",
            "labelFontSize": 11,
            "offset": 6
          }
        },
        "tooltip": [
          {
            "field": "Node Name",
            "title": "Node"
          },
          {
            "field": "kind",
            "title": "Type"
          },
          {
            "field": "status",
            "title": "Status"
          },
          {
            "field": "execution_time",
            "title": "Seconds",
            "format": ".1f"
          }
        ]
      }
    },
    {
      "transform": [
        {
          "filter": "datum.end_s - datum.start_s > 30"
        },
        {
          "calculate": "datum[''Node Name''] + ''  ·  '' + format(datum.execution_time, ''.0f'') + ''s''",
          "as": "lbl"
        }
      ],
      "mark": {
        "type": "text",
        "align": "left",
        "dx": 8,
        "fontSize": 11,
        "fontWeight": 600,
        "color": "#FFFFFF"
      },
      "encoding": {
        "text": {
          "field": "lbl"
        }
      }
    }
  ],
  "config": {
    "view": {
      "stroke": null
    },
    "font": "Segoe UI"
  }
}'
